-- The built-in themes, seasons, occasions and genres (issue #37), from TAG_VOCABULARY in @oneverse/core.
-- Upserted by slug like the seed; only built-in (global) tags are touched. A tag on songs is never removed: one merged into another is retired.
ALTER TABLE "Tag" ADD COLUMN "group" TEXT, ADD COLUMN "aliases" JSONB, ADD COLUMN "retired" BOOLEAN NOT NULL DEFAULT false;

INSERT INTO "TagCategory" ("id", "slug", "label", "translations", "sortOrder", "isGlobal", "updatedAt") VALUES
  ('tagcat_theme', 'theme', 'Theme', '{"fr":"Thème"}'::jsonb, 0, true, CURRENT_TIMESTAMP),
  ('tagcat_season', 'season', 'Season', '{"fr":"Saison"}'::jsonb, 1, true, CURRENT_TIMESTAMP),
  ('tagcat_occasion', 'occasion', 'Occasion', '{"fr":"Occasion"}'::jsonb, 2, true, CURRENT_TIMESTAMP),
  ('tagcat_style', 'style', 'Genre', '{"fr":"Genre"}'::jsonb, 3, true, CURRENT_TIMESTAMP),
  ('tagcat_mood', 'mood', 'Mood / Energy', '{"fr":"Ambiance"}'::jsonb, 4, true, CURRENT_TIMESTAMP),
  ('tagcat_instrumentation', 'instrumentation', 'Instrumentation', '{"fr":"Instrumentation"}'::jsonb, 5, true, CURRENT_TIMESTAMP)
ON CONFLICT ("slug") DO UPDATE SET "label" = EXCLUDED."label", "translations" = EXCLUDED."translations", "sortOrder" = EXCLUDED."sortOrder", "updatedAt" = CURRENT_TIMESTAMP;

